335	// ---------------------------------------------------------------------------
336	// 用例 4: 短毛刺无保护剪除 —— 无保护点时毛刺被清除，主干道完好
337	// ---------------------------------------------------------------------------
338	
339	TEST(SkeletonExtractorTest, ShortBristleUnprotected_PrunedMainLineIntact) {
340	  const BinaryGrid corridor = MakeCorridorWithBristle();
341	  const BinaryGrid skeleton = ZhangSuenThinning(corridor);
342	
343	  // 细化后毛刺分支确实存在：(15,3)..(15,7) 共 5 个像素挂在主干上。
344	  ASSERT_EQ(skeleton.GetValue(15, 7), 1);
345	  ASSERT_EQ(skeleton.GetValue(15, 6), 1);
346	  ASSERT_EQ(skeleton.GetValue(15, 5), 1);
347	  ASSERT_EQ(skeleton.GetValue(15, 4), 1);
348	  ASSERT_EQ(skeleton.GetValue(15, 3), 1);
349	  ASSERT_EQ(skeleton.GetValue(15, 2), 1) << "分叉点位于主干中心线";
350	  const int before = CountSkeleton(skeleton);
351	
352	  PruneConfig config;  // min_branch_length_m = 0.5, resolution = 0.05
353	  const BinaryGrid pruned =
354	      PruneSkeletonProtected(skeleton, {}, config);
355	
356	  // 短毛刺（0.25m < 0.5m，无保护）被完整剪除。
357	  EXPECT_EQ(pruned.GetValue(15, 7), 0);
358	  EXPECT_EQ(pruned.GetValue(15, 6), 0);
